// A load that finishes sooner than this never flashes the logo.
const SHOW_DELAY_MS = 150;

function LoadingLogo({ className, text, size = "default", ...props }: LoadingLogoProps) {
  const [show, setShow] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setShow(true), SHOW_DELAY_MS);
    return () => clearTimeout(timer);
  }, []);

  // Hidden rather than absent during the delay: the space is held from the first frame, so the logo appearing (or
  // the content replacing it) does not push the page down.
  return (
    <div
      data-slot="loading-logo"
      data-size={size}
      data-state={show ? "visible" : "delayed"}
      className={cn(
        "flex flex-col items-center justify-center",
        size === "sm" ? "gap-1.5 py-3" : "gap-3 py-12",
        !show && "invisible",
        className,
      )}
      {...props}
    >
      <svg
        viewBox="0 0 729 790"
        aria-hidden="true"
        className={cn("text-primary", size === "sm" ? "size-8" : "size-24")}
        xmlns="http://www.w3.org/2000/svg"
      >
        {PATHS.map((path) => (
          <path
            key={path.delay}
            d={path.d}
            transform={path.transform}
            fill="currentColor"
            stroke="currentColor"
            strokeWidth={4}
            strokeLinejoin="round"
            strokeLinecap="round"
            className="logo-trace"
            style={{
              strokeDasharray: 15000,
              animationDelay: path.delay,
            }}
          />
        ))}
      </svg>
      {text && <p className={cn("text-muted-foreground", size === "sm" ? "text-xs" : "text-sm")}>{text}</p>}
    </div>
  );
}

interface LoadingStateProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** What is loading, for assistive technology: "hero stats". */
  label?: string;
  /** A visible line under the logo, when the wait deserves an explanation: "Loading matches…". */
  text?: React.ReactNode;
  /**
   * - `logo`: the brand loader, with optional text under it.
   * - `skeleton`: a block of the final height, for a chart or a panel, so the layout does not jump.
   */
  variant?: "logo" | "skeleton";
  /** `sm` fits a panel, a popover or a table row; `default` stands in for a page or a tab. */
  size?: "sm" | "default";
  /** `center` fills the parent and sits in its middle, with room above and below: a tab, a panel, a page. */
  align?: "start" | "center";
  /** Sizes the skeleton, or positions the logo. */
  className?: string;
}

/** A region that is loading. A control that is busy uses Spinner instead. */
export function LoadingState({
  label = "content",
  text,
  variant = "logo",
  size,
  align = "start",
  className,
  ...props
}: LoadingStateProps) {
  if (variant === "skeleton") {
    return (
      <div data-slot="loading-state" data-variant="skeleton" className="relative" {...props}>
        <output className="sr-only">Loading {label}</output>
        <Skeleton className={cn("h-40 w-full rounded-xl", className)} />
      </div>
    );
  }
  return (
    <div
      data-slot="loading-state"
      data-variant="logo"
      data-align={align}
      className={cn(
        align === "center" && "flex size-full flex-1 items-center justify-center",
        align === "center" && (size === "sm" ? "py-8" : "py-16"),
        className,
      )}
      {...props}
    >
      {!text && <output className="sr-only">Loading {label}</output>}
      <LoadingLogo size={size} text={text && <output>{text}</output>} />
    </div>
  );
}
